      why: "ধরুন একটি ব্যাচে 3টি স্টাইল, মোট 6,000 পিস, CM পিসপ্রতি 45 টাকা, অর্থাৎ 2,70,000 টাকা। ফ্যাক্টরি পুরোটা চাইছে, কিন্তু 40 পিস হারিয়েছে, 2% ছাড়ের বেশি 85 পিস রিজেক্ট, আর আগেই 1,00,000 টাকা অগ্রিম নিয়েছে। হাতে হিসাব করলে কিছু বাদ পড়ে যায়, আর ফ্যাক্টরির সাথে তর্ক হয়। এই পাতা প্রতিটি কাটাকাটি কারণসহ এক জায়গায় দেখায়, ফ্যাক্টরিকে দেওয়ার মতো PDF বিল বানায়, আর কাটাকাটির টাকা নিজে থেকে তার Supplier Due থেকে কমায়।",
