          text: "হিসাব: Total CM − Deductions − Advance taken = Final payable। ঠিক থাকলে “Save and make the PDF bill” চাপুন। এরপর “Download the PDF bill” দিয়ে ফ্যাক্টরির বিল নামান; Accounts-কে শেষ পাওনা জানানো হয়।",
